//! Ordinary selected received DATA -> iterative planner -> funded literal child
//! -> reviewed second DATA -> independent finite recipient, without copying the
//! ancestor note or transferring any model consent. Both free synthetic engines.
use super::*;
use crate::pet_runtime::lease_controller::memory_test_http_fixture_idle as idle_http;

fn exercise_received(provider:&'static str,revoke_before_child:bool){exercise_received_with_notes(provider,revoke_before_child,false)}
fn exercise_received_with_notes(provider:&'static str,revoke_before_child:bool,selected_own:bool){
 let(f,a,ancestor,main,receipt)=source(provider,false);let receipt=receipt.unwrap();
 let own=if selected_own{let pet=&receipt.envelope().recipient.pet_id;let mut note=Fixture::record("recipient-own-note",pet,None);note["content"]=json!("PRIVATE_RECIPIENT_OWN_NOTE");f.write(vec![Fixture::record("selected-source-note",&ancestor.spec.owner.pet_id,None),note]);selected_with_memory(&f,&main,&receipt,Some(&[Fixture::selected("recipient-own-note")]))}else{selected(&f,&main,&receipt)};let f=Arc::new(f);let middle=if provider=="ollama"{"lmstudio"}else{"ollama"};let target=ancestor.spec.owner.pet_id.clone();let now=crate::assistant_memory::now();let deadline=own.spec.received_from.as_ref().unwrap().body.source.deadline_at;
 let first=json!({"kind":"plan","description":"Act on independently consented selected received data","steps":[{"description":"Fund a separately admitted deterministic branch","postcondition":"Local receipt, no implicit success","operation":{"operationId":"pet.delegate","version":1,"arguments":{"toPetId":target,"subgoal":"Own selected-received-data literal work","criteria":[NATIVE_MESSAGE_CRITERION],"expiresAt":deadline,"allowance":{"modelCalls":0,"toolCalls":1,"outputBytes":16384},"maxDepth":2}}}]});
 let second=json!({"kind":"plan","description":"Use source and fresh exact child metadata","steps":[{"description":"Deliver a reviewed transitive derived request","postcondition":"Receipt only; recipient consent remains separate","operation":{"operationId":"pet.message","version":1,"arguments":{"toPetId":target,"kind":"request","text":"MEMORY_DERIVED_AFTER_CHILD","expiresAt":deadline}}}]});
 let mut replies=vec![("application/json",meta(middle).to_string()),("text/event-stream",stream(&first.to_string(),true))];if !revoke_before_child{replies.extend([("application/json",meta(middle).to_string()),("text/event-stream",stream(&second.to_string(),true))]);}let(mut server,http)=idle_http(replies,|_|{});server.id=middle;
 let mut cap=budget(deadline,8);cap.max_model_calls=4;let prepare=||Review::prepare_planning_catalog(&own,evidence(&f,&own,&server),cap.clone(),Limits{max_rounds:2,max_steps:2,max_output_bytes:2048,no_progress_limit:2},&configuration(),Catalog::PeerDelegationIterationV1,nonce().unwrap(),nonce().unwrap(),crate::assistant_memory::now());
 let denied=prepare().unwrap();assert_eq!(denied.approve(&own,evidence(&f,&own,&server),crate::assistant_memory::now()).err(),Some(Denial::DataConsentRequired));
 let approved=prepare().unwrap().approve_with_data(&own,evidence(&f,&own,&server),Some(crate::pet_memory::context_model::GoalConsent::BoundedGoalContext),crate::assistant_memory::now()).unwrap();assert_eq!(approved.spec().schema_version,25);assert!(approved.spec().peer_received_iteration());
 // An old finite review cannot acquire iterative tool/model limits.
 assert!(Review::prepare(&own,evidence(&f,&own,&server),cap.clone(),nonce().unwrap(),nonce().unwrap(),now).is_err());
 let snapshot=crate::pet_runtime::planned_peer_data::Snapshot::from_spec(approved.spec()).unwrap().unwrap();assert_eq!(snapshot.schema_version,4);assert_eq!(snapshot.references.len(),usize::from(selected_own));if selected_own{assert_eq!(snapshot.references[0].id,"recipient-own-note");}assert_eq!(snapshot.received_request.as_deref(),own.execution_context.as_ref().unwrap().received_request.as_ref());
 let cert=a.certify(&approved,&own,crate::assistant_memory::now()).unwrap();let queued=native(&f).enqueue_certified(&cert,crate::assistant_memory::now()).unwrap().record;assert_eq!(queued.schema_version,58);
 let p=Controller::new().unwrap().prepare_memory_fixture(&queued,&f.root.join("authority"),&f.contexts(),&f.catalog(),&main,&evidence(&f,&queued,&server),nonce().unwrap(),crate::assistant_memory::now(),Arc::new(|_,_,_|Validity::Current)).unwrap();let(leased,owner)=p.claim(&native(&f),&a,&evidence(&f,&queued,&server),crate::assistant_memory::now()).unwrap();let owner=Arc::new(owner.unwrap());
 let environment=if selected_own{iterative_memory::received_environment_with_memory(f.clone(),main.clone(),owner.clone(),middle,server.url.clone(),revoke_before_child,true)}else{iterative_memory::received_environment(f.clone(),main.clone(),owner.clone(),middle,server.url.clone(),revoke_before_child)};let driver=Driver::new(owner.clone(),Arc::new(native(&f)),environment).unwrap();let status=iterative_memory::drive(driver);let requests=http.join().unwrap();let current=native(&f).read(&leased.record.id,&own.spec.owner.pet_id).unwrap();assert!(current.completion.is_none());assert_eq!(owner.workers(),0);assert_eq!(requests.len(),if revoke_before_child{2}else{4},"{status:?}");
 let text=requests[1].1["messages"].to_string();assert!(text.contains("DERIVED_APPROVED_TEXT_ONLY"));assert_eq!(text.contains("PRIVATE_RECIPIENT_OWN_NOTE"),selected_own);for private in ["PRIVATE_GOAL_MEMORY_SENTINEL","selected-source-note",receipt.envelope().origin.lease_id.as_str(),receipt.envelope().origin.controller_id.as_str()]{assert!(!text.contains(private),"Raw ancestor data/control escaped its native selection");}
 let children=native(&f).list(Some(&target)).unwrap();let child=children.goals.iter().filter_map(|g|native(&f).read(&g.id,&target).ok()).find(|g|g.schema_version==60).expect("native funded child60 must be admitted");
 if revoke_before_child{assert!(status.is_err()||current.state!=State::Completed);assert!(child.completion.is_none());return;}
 assert_eq!(status.unwrap().phase,Phase::AwaitingVerification);assert!(child.completion.is_some());let second_body=&requests[3].1;assert!(second_body["messages"].to_string().contains("ownDelegatedOutcomeMetadata"));assert!(second_body["messages"].to_string().contains("DERIVED_APPROVED_TEXT_ONLY"));assert!(!second_body["messages"].to_string().contains("PRIVATE_GOAL_MEMORY_SENTINEL"));assert_eq!(second_body["messages"].to_string().contains("PRIVATE_RECIPIENT_OWN_NOTE"),selected_own);
 let inbox=a.message_inbox(&target,None,8,crate::assistant_memory::now()).unwrap();let transitive=&inbox.items.iter().find(|i|i.receipt.envelope().schema_version==15).expect("one transitive request15").receipt;let data=transitive.envelope().planned_data.as_ref().unwrap();assert_eq!(data.schema_version,4);assert!(data.round_data.is_some());assert!(data.source.received_request.is_some());let metadata=data.model_metadata().to_string();assert!(metadata.contains("plannedPeerSelectedReceivedAndRoundDerivedData"));assert!(!metadata.contains("selected-source-note"));assert!(!transitive.envelope().provider_use_authorized);
 // Read back exact46 shared usage; neither recipient data use nor peer results
 // renew the planner's original allowance or mark its free criterion complete.
 let grant:Value=serde_json::from_slice(&fs::read(f.root.join("authority").join(format!("{}.json",current.admissions[0].spec.decision_id))).unwrap()).unwrap();assert_eq!(grant["body"]["schemaVersion"],46);assert_eq!(grant["body"]["delegationPool"],serde_json::to_value(&cap).unwrap());assert_eq!(grant["body"]["messages"]["entries"].as_array().unwrap().len(),2);assert_eq!(grant["body"]["planningUsage"]["rounds"].as_array().unwrap().len(),2);for (index,request) in [&requests[1].1,&requests[3].1].into_iter().enumerate(){let hash=model::fingerprint(&(&owner.lease().id,"fixture-free",request)).unwrap();assert_eq!(grant["body"]["planningUsage"]["rounds"][index]["inputHash"],hash);assert!(grant["body"]["budgetUsage"]["attempts"].as_array().unwrap().iter().any(|a|a["kind"]=="model"&&a["inputHash"]==hash&&a["phase"]=="settled"));}
 let final_goal=selected(&f,&main,transitive);assert_eq!(final_goal.schema_version,59);let final_provider=provider;let(mut destination,finish)=idle_http(vec![("application/json",meta(final_provider).to_string()),("text/event-stream",stream("Own independent transitive analysis",true))],|_|{});destination.id=final_provider;let(g,o)=admit(&f,&a,&final_goal,&destination,&main);let environment=Arc::new(Env{server:Some(destination),revoke:None,choice:false});let driver=Driver::new(o.clone(),Arc::new(native(&f)),environment).unwrap();assert_eq!(iterative_memory::drive(driver).unwrap().phase,Phase::AwaitingVerification);let requests=finish.join().unwrap();assert_eq!(requests.len(),2);let body=&requests[1].1;assert!(body["messages"].to_string().contains("MEMORY_DERIVED_AFTER_CHILD"));for private in ["PRIVATE_GOAL_MEMORY_SENTINEL","PRIVATE_RECIPIENT_OWN_NOTE","recipient-own-note","selected-source-note",receipt.envelope().origin.lease_id.as_str(),transitive.envelope().origin.lease_id.as_str()]{assert!(!body["messages"].to_string().contains(private));}assert!(native(&f).read(&g.id,&g.spec.owner.pet_id).unwrap().completion.is_none());
}
#[test]fn received_context_iteration_uses_own_f2_native_child_and_exact_second_data_on_both_engines(){for p in ["ollama","lmstudio"]{exercise_received(p,false);}}
#[test]fn received_context_iteration_ancestor_revocation_after_child_claim_blocks_new_effects(){exercise_received("ollama",true);}

// This uses actual native receipts at every hop. No JSON-only source can stand
// in for a source grant, own F2, acknowledged publication or received envelope.
struct ChainEnv{provider:&'static str,url:String}
impl Environment for ChainEnv{
 fn capture(&self,_:&Owned)->model::Result<dispatcher::Capture>{Ok(dispatcher::Capture{configuration:configuration(),server:crate::local_chat::Server{id:self.provider,name:"Bounded transitive fixture",url:self.url.clone(),key:None},app:None})}
 fn configuration(&self)->model::Result<crate::pet_config::Configuration>{Ok(configuration())}
 fn peer_configuration(&self)->model::Result<(crate::pet_config::Configuration,crate::settings::Settings)>{Ok((configuration(),settings()))}
 fn target(&self)->model::Result<Arc<crate::spotify::goal::Target>>{panic!("No system or media IO")}
 fn notify(&self,_:&dispatcher::Status){}
 fn decide(&self,source:Source)->Option<Decision>{assert_eq!(source.review()["recipe"]["steps"][0]["envelope"]["schemaVersion"],15);let decision=crate::cli_chat::goal_decision_fixture(source);decision.panel_answer(true,decision.request["goalTarget"].clone()).unwrap();decision.decision()}
}
#[test]
fn received_context_iteration_chain_stops_at_native_depth_before_another_model_reservation(){
 let(f,a,ancestor,main,receipt)=source_for("ollama",false,300_000);let mut receipt=receipt.unwrap();let cap_depth=crate::pet_runtime::received_result_data::MAX_SOURCE_DEPTH;
 for depth in 1..=cap_depth{
  let own=selected(&f,&main,&receipt);let provider=if own.spec.owner.pet_id=="ai_ollama"{"ollama"}else{"lmstudio"};let deadline=own.spec.received_from.as_ref().unwrap().body.source.deadline_at;let destination=if provider=="ollama"{"ai_lmstudio"}else{"ai_ollama"};
  let selection=own.execution_context.as_ref().unwrap().received_request.as_ref().unwrap();let capture=crate::pet_runtime::received_context::Captured::at_with_memory(&f.root.join("authority"),&f.catalog(),&own,selection,crate::assistant_memory::now()).unwrap();assert_eq!(capture.source_depth(),depth);
  if depth==cap_depth{
   let server=crate::local_chat::Server{id:provider,name:"Passive only at depth bound",url:"http://127.0.0.1:1".into(),key:None};let before=native(&f).list(None).unwrap().goals.len();let mut cap=budget(deadline,1);cap.max_model_calls=1;
   let review=Review::prepare_planning_catalog(&own,evidence(&f,&own,&server),cap,Limits{max_rounds:1,max_steps:1,max_output_bytes:2048,no_progress_limit:1},&configuration(),Catalog::PeerDelegationIterationV1,nonce().unwrap(),nonce().unwrap(),crate::assistant_memory::now());assert_eq!(review.err(),Some(Denial::Unsupported));assert!(native(&f).read(&own.id,&own.spec.owner.pet_id).unwrap().admissions.is_empty());assert_eq!(native(&f).list(None).unwrap().goals.len(),before);
   // The source remains valid DATA for a separately consented finite response.
   assert!(Review::prepare(&own,evidence(&f,&own,&server),budget(deadline,0),nonce().unwrap(),nonce().unwrap(),crate::assistant_memory::now()).is_ok());break;
  }
  let proposal=json!({"kind":"plan","description":"One bounded transitive request","steps":[{"description":"Deliver reviewed derived text","postcondition":"Local receipt only","operation":{"operationId":"pet.message","version":1,"arguments":{"toPetId":destination,"kind":"request","text":format!("TRANSITIVE_DEPTH_{depth}"),"expiresAt":deadline}}}]});
  let(mut server,http)=idle_http(vec![("application/json",meta(provider).to_string()),("text/event-stream",stream(&proposal.to_string(),true))],|_|{});server.id=provider;
  let review=Review::prepare_planning_catalog(&own,evidence(&f,&own,&server),budget(deadline,1),Limits{max_rounds:1,max_steps:1,max_output_bytes:2048,no_progress_limit:1},&configuration(),Catalog::PeerDelegationIterationV1,nonce().unwrap(),nonce().unwrap(),crate::assistant_memory::now()).unwrap();let approved=review.approve_with_data(&own,evidence(&f,&own,&server),Some(crate::pet_memory::context_model::GoalConsent::BoundedGoalContext),crate::assistant_memory::now()).unwrap();let cert=a.certify(&approved,&own,crate::assistant_memory::now()).unwrap();let q=native(&f).enqueue_certified(&cert,crate::assistant_memory::now()).unwrap().record;
  let prepared=Controller::new().unwrap().prepare_memory_fixture(&q,&f.root.join("authority"),&f.contexts(),&f.catalog(),&main,&evidence(&f,&q,&server),nonce().unwrap(),crate::assistant_memory::now(),Arc::new(|_,_,_|Validity::Current)).unwrap();let(leased,owner)=prepared.claim(&native(&f),&a,&evidence(&f,&q,&server),crate::assistant_memory::now()).unwrap();let owner=Arc::new(owner.unwrap());let environment=Arc::new(ChainEnv{provider,url:server.url.clone()});let driver=Driver::new(owner.clone(),Arc::new(native(&f)),environment).unwrap();assert_eq!(iterative_memory::drive(driver).unwrap().phase,Phase::AwaitingVerification);assert_eq!(http.join().unwrap().len(),2);assert_eq!(owner.workers(),0);
  let current=native(&f).read(&leased.record.id,&own.spec.owner.pet_id).unwrap();let publication=current.generated_plans.last().unwrap();let step=&current.plans.iter().find(|p|p.id==publication.plan_id).unwrap().steps[0];receipt=a.message_at(&current.admissions[0].spec,current.admissions[0].proof.as_ref().unwrap(),&publication.plan_id,&step.id).unwrap().unwrap();assert_eq!(receipt.envelope().schema_version,15);assert!(current.completion.is_none());
 }
 assert!(native(&f).read(&ancestor.id,&ancestor.spec.owner.pet_id).unwrap().completion.is_some());
}

